#import <UIKit/UIKit.h>
#import <stdint.h>
static uint32_t HLIconBE(const uint8_t *p){return ((uint32_t)p[0]<<24)|((uint32_t)p[1]<<16)|((uint32_t)p[2]<<8)|p[3];}
BOOL HLWriteImportedGameIcons(NSString *originalApp,NSString *outputApp,NSMutableDictionary *info,NSError **error){
 NSString *path=[originalApp stringByAppendingPathComponent:@"Contents/Resources/PlayerIcon.icns"];NSData *icns=[NSData dataWithContentsOfFile:path options:NSDataReadingMappedIfSafe error:error];NSString *executable=[NSDictionary dictionaryWithContentsOfFile:[originalApp stringByAppendingPathComponent:@"Contents/Info.plist"]][@"CFBundleExecutable"];NSString *game=[executable containsString:@"Silksong"]?@"silksong":@"hollow-knight";UIImage *preferred=[UIImage imageWithContentsOfFile:[NSBundle.mainBundle.bundlePath stringByAppendingPathComponent:[NSString stringWithFormat:@"Branding/%@.png",game]]];UIImage *best=nil;
 if(icns.length>=8&&!memcmp(icns.bytes,"icns",4)&&HLIconBE((const uint8_t *)icns.bytes+4)==icns.length){const uint8_t *bytes=icns.bytes;NSUInteger offset=8;while(offset+8<=icns.length){uint32_t count=HLIconBE(bytes+offset+4);if(count<8||count>icns.length-offset)break;NSUInteger length=count-8;if(length>=8&&!memcmp(bytes+offset+8,"\x89PNG\r\n\x1a\n",8)){UIImage *image=[UIImage imageWithData:[icns subdataWithRange:NSMakeRange(offset+8,length)]];if(image.size.width>best.size.width)best=image;}offset+=count;}}
 if(preferred)best=preferred;
 if(!best){if(error)*error=[NSError errorWithDomain:@"HollowIcons" code:1 userInfo:@{NSLocalizedDescriptionKey:@"The original game icon contains no supported PNG image."}];return NO;}
 for(NSNumber *number in @[@120,@180,@1024]){CGFloat size=number.doubleValue;UIGraphicsImageRendererFormat *format=[UIGraphicsImageRendererFormat defaultFormat];format.scale=1;format.opaque=YES;UIGraphicsImageRenderer *renderer=[[UIGraphicsImageRenderer alloc]initWithSize:CGSizeMake(size,size) format:format];UIImage *icon=[renderer imageWithActions:^(UIGraphicsImageRendererContext *context){[UIColor.blackColor setFill];UIRectFill(CGRectMake(0,0,size,size));[best drawInRect:CGRectMake(0,0,size,size)];}];NSString *name=size==120?@"AppIcon60x60@2x.png":size==180?@"AppIcon60x60@3x.png":@"AppIcon1024.png";if(![UIImagePNGRepresentation(icon) writeToFile:[outputApp stringByAppendingPathComponent:name] options:NSDataWritingAtomic error:error])return NO;}
 NSDictionary *primary=@{@"CFBundleIconFiles":@[@"AppIcon60x60"],@"UIPrerenderedIcon":@NO};info[@"CFBundleIcons"]=@{@"CFBundlePrimaryIcon":primary};info[@"CFBundleIcons~ipad"]=@{@"CFBundlePrimaryIcon":primary};return YES;
}
